insert into project_cost_models (cost_model_id, project_id, title, case_kind, case_label, version_label, status, source_url, source_note, summary_md, visibility, created_by, updated_by) values ('cm_p21_260820', 'p21', 'SX コスト試算', 'dye_degradation', '色素分解', '260820版', 'active', 'https://docs.google.com/spreadsheets/d/1ZGYjuQ-7grss83gVrVZ7jV7zd76AVuWDPqwi-JDjmVw/edit', '原典: Google Sheets SX_コスト試算_260820 (ちこ)。中島先生の設備・運用想定を反映した版。', 'ちこ作成の260820版をAMD OSへ移した初版。\n\n**ケースの注意**: 260820スプレッドシートには「色素」「脱色」「染料」の語が1つも無く、必要菌体量が `金属濃度 ÷ 取り込み効率α(g金属/g菌体)` で回っていた。まさの確認では今の対象は色素分解。設備構成(A循環/B投入/C中央培養)は両ケース共通なので、設備明細はそのまま使えるが、濃度・取り込み効率・酸処理まわりは色素の条件へ差し替えが要る。この版はケースを色素分解として登録し、差し替え待ちの行を要確認として残している。', 'amd_internal', 'amie', 'amie');
