insert into project_cost_assumptions (cost_assumption_id, cost_model_id, group_label, label, value, unit, confidence, source_kind, owner, is_key, role_key, note, sort_order) values ('ca_reuse_count', 'cm_p21_260820', '対象物質', '菌体使用回数（1＝使い捨て）', 1.0, '回', 'H', '要検証', '杉浦先生', true, 'reuse_count', '★最大の感度。1＝再利用せず毎回新品。技術的事実ではない保守的仮定。まさの記憶では色素分解なら数十回使い回せる可能性があるが未確認（2026-08-23時点でうろ覚えと明言）。10回を超えると中央培養コストは誤差になる。MTGで判定する。', 130);
