insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, sort_order) values ('ci_260820_083', 'cm_p21_260820', '循環', 'CAPEX', '反応・回収設備', '簡易水洗設備', '洗浄設備', '初期投資配賦', 1.0, '式', 300000.0, '円/式', null, 1.0, 10.0, false, 'C', '先生回答', '中島先生', 'CIP装置ではなく簡易水洗設備。処理終了後に「清水→循環配管→カートリッジ周辺配管→排水回収」と流して残液や遊離菌体を洗い流すためのもの。内訳は清水接続または小型リンス水槽／ホース／バルブ／洗浄用接続口／洗浄排水回収容器／必要に応じ簡易スプレーノズル程度。循環には既設ペリスタルポンプを共用するため専用洗浄ポンプは原則不要。菌体保持モジュール自体の現場薬品洗浄は想定せず、金属を含むモジュールは回収して別拠点で再生・金属回収を行う。', 410);
insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, sort_order) values ('ci_260820_084', 'cm_p21_260820', '循環', 'CAPEX', '反応・回収設備', '　└ 清水接続または小型リンス水槽', '洗浄設備', '内訳', 1.0, '式', 0.0, '円/式', null, 1.0, 10.0, true, null, '先生回答', '中島先生', '簡易水洗設備30万円の内訳。循環には既設ペリスタルポンプを共用するため専用洗浄ポンプは原則不要。各項目の金額は今後個別に確定させ、確定後は親行を子行の合計に切替える。', 420);
