insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, sort_order) values ('ci_260820_092', 'cm_p21_260820', '投入', 'CAPEX', '反応・分離設備', '菌体分離設備（UF/MFスキッド恒久部）', '分離設備', '初期投資配賦', 1.0, '式', 8000000.0, '円/式', null, 1.0, 10.0, false, 'H', '予測', 'ダイキアクシス', '★当方予測による分離：先生回答B④で1,200万円は膜だけでなくスキッド一式（膜ハウジング／供給ポンプ／配管／バルブ／流量計／圧力計／TMP監視／透過水・濃縮菌体ライン／架台／基本制御）を含むと明確化された。一方で従来は1,200万円全額を膜交換年数3年で償却しており、恒久設備まで3年で落とす過大計上になっていた。そこで恒久部800万円（10年）と膜モジュール400万円（3年）に暫定分割。内訳金額は未確定のため当方予測。【最重要確認・ダイキアクシス】UF/MFスキッド1,200万円のうち約3年で交換する膜モジュール部分はいくらか。ハウジング・ポンプ・配管・制御等の恒久設備部分はいくらか。', 500);
insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, sort_order) values ('ci_260820_093', 'cm_p21_260820', '投入', 'CAPEX', '反応・分離設備', 'UF/MF膜モジュール（交換品）', '分離設備', '初期投資配賦', 1.0, '式', 4000000.0, '円/式', null, 1.0, 3.0, false, 'H', '予測', 'ダイキアクシス', '★当方予測：UF/MFスキッド1,200万円のうち、約3年で交換する膜モジュール部分を400万円と暫定。耐用年数はB34（膜交換年数3年・260812打合せで中島先生から確認）に連動。Aの「カートリッジ群＝恒久設備／菌体保持モジュール＝交換品」と同じ考え方でBにも適用した。内訳金額はダイキアクシスへ要確認。', 510);
insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, sort_order) values ('ci_260820_094', 'cm_p21_260820', '投入', 'CAPEX', '反応・分離設備', '　└ UF/MF膜モジュール', '分離設備', '内訳', 1.0, '式', 0.0, '円/式', null, 1.0, 3.0, true, null, '先生回答', '中島先生', 'UF/MF膜分離スキッド一式1,200万円の内訳。流量計はここに含まれるため、投入方式の独立項目としての流量計30万円は削除済み。各項目の金額は今後個別に確定させ、確定後は親行を子行の合計に切替える。', 520);
