insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, sort_order) values ('ci_260820_106', 'cm_p21_260820', '投入', 'CAPEX', '反応・分離設備', '使用済み菌体／保持モジュール一時保管・搬送設備', '回収', '初期投資配賦', 1.0, '式', 50000.0, '円/式', null, 1.0, 10.0, false, 'C', '先生回答', '中島先生', 'カートリッジ群そのものを収納する巨大容器ではなく、金属を取り込んだシアノを含む菌体保持モジュールを、酸処理・金属回収工程へ送るまで安全に一時保管・搬送するための設備。運用は「モジュールを密閉容器へ収納→一時保管→再生・金属回収拠点へ搬送」。金額は保守的な仮置きで、実際は20〜100万円のレンジ（PE容器・IBC・ドラム等で足りる可能性あり）。必要菌体量が確定してから見直す。', 640);
