insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, sort_order) values ('ci_260820_111', 'cm_p21_260820', '投入', 'CAPEX', '反応・分離設備', '流量計（削除・UF/MF設備一式に含む）', '計装', '初期投資配賦', 1.0, '式', 0.0, '円/式', null, 1.0, 10.0, false, 'H', '先生回答', '中島先生', '直接投入方式では、菌体を100m³槽へ投入し撹拌してバッチ反応させるだけなので、反応工程そのものに循環流量計は不要。一方でUF/MFへの供給流量・透過水流量・逆洗流量の管理には流量計が必要だが、これはUF/MF分離設備一式（1,200万円）の内訳にすでに含まれている。したがって本行の30万円は二重計上にあたるため削除し、UF/MF設備側に一本化する。UF/MF側の金額は据え置き。', 690);
insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, sort_order) values ('ci_260820_112', 'cm_p21_260820', '投入', 'CAPEX', '反応・分離設備', '自動制御システム', '制御', '初期投資配賦', 1.0, '式', 4400000.0, '円/式', null, 1.0, 10.0, false, 'C', '先生回答', '中島先生', '○', 700);
insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, sort_order) values ('ci_260820_113', 'cm_p21_260820', '投入', 'CAPEX', '反応・分離設備', 'UF/MF逆洗・CIP設備', '洗浄設備', '初期投資配賦', 1.0, '式', 2000000.0, '円/式', null, 1.0, 10.0, false, 'C', '先生回答', '中島先生', '循環方式の簡易水洗設備30万円とは内容が異なる。UF/MF膜を使用するため、リンス水槽／洗浄ポンプ／UF/MF逆洗／洗浄配管・バルブ／洗浄排水回収／薬液循環用の簡易設備までを含むUF/MF用簡易CIP設備一式として仮置き。通常運転時の水逆洗だけでなく、膜性能低下時の薬液洗浄もできる構成を想定。ただし200万円はメーカー見積前の仮置きのため、UF/MFメーカーへ要確認。', 710);
insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, sort_order) values ('ci_260820_114', 'cm_p21_260820', '投入', 'CAPEX', '反応・分離設備', '　└ リンス水槽', '洗浄設備', '内訳', 1.0, '式', 0.0, '円/式', null, 1.0, 10.0, true, null, '先生回答', '中島先生', 'UF/MF逆洗・CIP設備200万円の内訳。通常運転時の水逆洗だけでなく、膜性能が低下した際の薬液洗浄もできる構成を想定。200万円はメーカー見積前の仮置きのため、UF/MFメーカーへ要確認。各項目の金額は今後個別に確定させ、確定後は親行を子行の合計に切替える。', 720);
