insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, sort_order) values ('ci_260820_149', 'cm_p21_260820', '循環', 'OPEX', '反応・カートリッジ/全体共通', '交換部品', '菌体保持モジュール交換費', '毎m³比例', 1.0, 'm³', 0.0, '円/m³', 'module_swap', 1.0, null, false, 'H', '予測', 'AMD', 'カートリッジ本体（恒久設備）とは別に、内部の菌体保持モジュール（菌体保持膜・バッグ・フィルター・内部支持材）を耐用バッチ数ごとに交換する費用。単価は実績未取得のため予測値。B40セルで変更可能。＝モジュール一式単価÷耐用バッチ数÷バッチ容量', 1070);
insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, sort_order) values ('ci_260820_150', 'cm_p21_260820', '循環', 'OPEX', '反応・カートリッジ/全体共通', '　└ 菌体保持膜', '交換部品', '内訳', 1.0, '式', 0.0, '円/式', null, 1.0, null, true, null, '先生回答', '中島先生', '菌体保持モジュール（交換・消耗部品）の内訳。カートリッジ本体（恒久設備）とは別に、耐用バッチ数ごとに交換する。シアノ菌体の扱い（再生・再利用の可否、回数）は未確定のため、上部30行の注記および102・103行と合わせて整理する。各項目の金額は今後個別に確定させる。', 1080);
