insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, sort_order) values ('ci_260820_154', 'cm_p21_260820', '循環', '参考', '反応・カートリッジ/全体共通', '　（参考）保持されるシアノ', '－', '内訳', 1.0, '式', 0.0, '円/式', null, 1.0, null, true, null, '先生回答', '中島先生', '菌体そのものはモジュール部材ではないため内訳から除外（金額0円）。シアノは中央培養拠点から供給され、菌体のロス・性能低下は141・142行（循環）／159・160行（投入）で別途計上している。モジュール（膜・バッグ・フィルター・支持材）と菌体は寿命が別物であるため分離して管理する。', 1120);
