insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, sort_order) values ('ci_260820_158', 'cm_p21_260820', '循環', 'OPEX', '全体共通', '増分電気代（循環ポンプ等、推定）', '電力', '毎m³比例', 1.0, 'm³', 0.0, '円/m³', 'power_circulation', 1.0, null, false, 'H', '推定', 'AMD', '260812打合せ：実消費電力ベースで推定。動力kW×HRT×電力単価÷バッチ容量。ワット数は仮定値のため、実測が入り次第「循環動力[kW]」セルを更新すればここも自動更新される。', 1160);
insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, sort_order) values ('ci_260820_159', 'cm_p21_260820', '循環', '参考', '人件費（参考・手動運用の場合）', '作業人件費', '1バッチ作業×バッチ数', 'バッチ連動', 5.75, 'h/バッチ', 4000.0, '円/h', null, 300.0, null, false, 'A', '先生回答', '中島先生', '1バッチ5.75h×年間バッチ回数×人件費単価。自動制御化（300〜400万円）で圧縮余地あり。｜※商用モデルは自動制御システム（CAPEX計上済）により自動化される前提のため、この人件費は①②の総コストには含めていない。手動運用する場合の参考値。', 1170);
insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, sort_order) values ('ci_260820_160', 'cm_p21_260820', '投入', 'OPEX', 'リアクター/分離回収/全体共通', '反応', '菌体ロス補充分', '毎m³比例', 1.0, 'm³', 10.0, '円/m³', 'biomass', 1.0, null, false, 'B', '仮置き', 'AMD', '物理的なロス分の補充。名称を「補充菌体」から明確化。現行は毎m³一定額の暫定計算で、菌体寿命の概念を持たない。菌体再利用可能バッチ数（上部注記参照）が確定したら式を組み直す。', 1180);
insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, sort_order) values ('ci_260820_161', 'cm_p21_260820', '投入', 'OPEX', 'リアクター/分離回収/全体共通', '反応', '菌体性能低下による交換・再生分', '毎m³比例', 1.0, 'm³', 5.0, '円/m³', 'biomass', 1.0, null, false, 'C', '仮置き', 'AMD', '菌体の金属吸収能力が落ちた分の交換・再生費用。名称を「性能低下見合い追加投入」から明確化。現行式は性能低下率を単純に追加投入する暫定計算。菌体の再生可否・再利用回数・再生コストが未確定のため、この式は暫定扱い。確定後に組み直す。', 1190);
